\mathsf{Ax}_{COK}^{601}
=\{O_G(A\to B\mid C)\to(O_G(A\mid C)\to O_G(B\mid C)):
A,B,C\in\mathsf{Aux}_{601}\},

\mathsf{Ax}_{Sh}^{601}
=\{O_G(A\mid B\land C)\to O_G(C\to A\mid B):
A,B,C\in\mathsf{Aux}_{601}\}.

\begin{aligned}
\mathsf{PrefMod}_{601}(M)\Longleftrightarrow
\exists W,r,V\ \bigl(&M=(W,r,V)\land W\ne\varnothing\\
&\land r\subseteq W\times W
\land V:\mathsf{Prop}\to\mathcal P(W)\bigr).
\end{aligned}

⟦ O_G(A\mid B)⟧_{601}^{M}
=
\begin{cases}
W,&\operatorname{opt}^{601}_{W,r}(⟦ B⟧_{601}^{M})\subseteq⟦ A⟧_{601}^{M},\\
\varnothing,&\operatorname{opt}^{601}_{W,r}(⟦ B⟧_{601}^{M})\nsubseteq⟦ A⟧_{601}^{M},
\end{cases}

M,w\Vdash_{601}A
\Longleftrightarrow w\in⟦ A⟧_{601}^{M}
\quad(\mathsf{PrefMod}_{601}(M),\ w\in W,\ A\in\mathsf{Aux}_{601}).
